    _settingsRepository = context.read<SettingsRepository>();
    _themeModeNotifier = ValueNotifier(_settingsRepository.readThemeMode());
    _themeSub = _settingsRepository.themeModeStream.listen((mode) {
      if (mounted) {
        _themeModeNotifier.value = mode;
      }
    });
    _initAnimation();
  }

  @override
  void dispose() {
    _themeModeNotifier.dispose();
    _themeSub.cancel();
    _alignmentController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _alignmentController = AnimationController(
      duration: const Duration(seconds: 2),
      vsync: this,
    )..repeat(reverse: true);
    _alignmentAnimation = _tween.animate(_alignmentController);
  }

